def has_duplicate(items):
    # O(n^2): compares every pair
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] == items[j]:
                return True
    return False

def has_duplicate_fast(items):
    # O(n): one pass, remembering what we have seen
    seen = set()
    for x in items:
        if x in seen:
            return True
        seen.add(x)
    return False

def first_pair_with_sum(nums, target):
    seen = {}                      # value -> index
    for j, x in enumerate(nums):
        if target - x in seen:
            return seen[target - x], j
        seen.setdefault(x, j)
    return None

def longest_unique(s):
    last, left, best = {}, 0, 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1          # jump past the repeat
        last[ch] = right
        best = max(best, right - left + 1)
    return best

def first_true(lo, hi, ok):
    # smallest x in [lo, hi) with ok(x) True, assuming ok is monotone; returns hi if none
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

